<template><main class="login-shell"><div class="aurora-orb orb-one"></div><div class="aurora-orb orb-two"></div><section class="login-card"><div class="login-brand"><span class="brand-logo"><i></i><i></i><i></i></span><span>Smart <b>CRM</b></span><div class="login-language"><button :class="{active:locale==='uk'}" @click="setLocale('uk')">UA</button><button :class="{active:locale==='en'}" @click="setLocale('en')">EN</button></div></div><div class="login-divider"></div><span class="eyebrow">{{ t('welcome') }}</span><h1>{{ t('signIn') }}</h1><p class="muted">{{ t('loginText') }}</p><form @submit.prevent="submit"><label>{{ t('email') }}<input v-model.trim="email" type="email" autocomplete="email" placeholder="you@company.com" required /></label><label>{{ t('password') }}<input v-model="password" type="password" autocomplete="current-password" placeholder="••••••••" required /></label><div v-if="error" class="alert alert-danger py-2">{{ error }}</div><button class="primary-btn" :disabled="loading">{{ loading ? '…' : t('continue') }} <span>→</span></button></form><p class="login-foot"><span>✦</span> {{ t('secureAccess') }}</p></section></main></template>
<script setup>
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { login } from '../api'; import { locale, setLocale, t } from '../i18n'
const router = useRouter(), email = ref(''), password = ref(''), error = ref(''), loading = ref(false)
async function submit() { loading.value = true; error.value = ''; try { await login(email.value, password.value); router.push('/') } catch (e) { error.value = e.message } finally { loading.value = false } }
</script>
